#!/usr/bin/env node
// Read-only SSR readback for the Aidreamcapes media product placement pilot.
//
// It checks:
//   - every tagged directory renders one card per product, with no duplicate
//     href or media source;
//   - every canonical detail page and one alias detail page render the same
//     category chip.
//
// The audit report defines the expected tagged products. It is generated by:
//   npm run audit:aidreamcapes-media-products
//
// Usage:
//   node scripts/smoke-aidreamcapes-media-product-placement.mjs
//   node scripts/smoke-aidreamcapes-media-product-placement.mjs --base-url=http://127.0.0.1:3002/site/aidreamcapes
import assert from "node:assert/strict";
import fs from "node:fs";
import * as cheerio from "cheerio";
import { argumentValue, hasArgument } from "./lib/database-target.mjs";

const DEFAULT_BASE_URL = "http://127.0.0.1:3002/site/aidreamcapes";
const DEFAULT_MANIFEST = "scripts/manifests/aidreamcapes-media-product-placement-local-2026-10-21.json";
const DEFAULT_AUDIT = "docs/audits/aidreamcapes-media-product-groups-2026-10-21.json";
const baseUrl = (argumentValue("--base-url") || DEFAULT_BASE_URL).replace(/\/+$/, "");
const basePath = new URL(baseUrl).pathname.replace(/\/+$/, "");
const manifestPath = argumentValue("--manifest") || DEFAULT_MANIFEST;
const auditPath = argumentValue("--audit") || DEFAULT_AUDIT;
const verbose = hasArgument("--verbose");

function text(value) {
  return typeof value === "string" && value.trim() ? value.trim() : undefined;
}

function normalizePath(value) {
  try {
    let pathname = new URL(value, baseUrl).pathname.replace(/\/+$/, "") || "/";
    if (basePath && (pathname === basePath || pathname.startsWith(`${basePath}/`))) {
      pathname = pathname.slice(basePath.length) || "/";
    }
    return pathname;
  } catch {
    return value;
  }
}

async function readPage(pathname, follow = false) {
  const response = await fetch(`${baseUrl}${pathname}`, {
    redirect: follow ? "follow" : "manual",
    signal: AbortSignal.timeout(20000)
  });
  const finalUrl = new URL(response.url);
  const origin = new URL(baseUrl), loopback = new Set(["localhost", "127.0.0.1", "[::1]"]);
  assert(finalUrl.origin === origin.origin || loopback.has(finalUrl.hostname) && loopback.has(origin.hostname)
    && finalUrl.port === origin.port && finalUrl.protocol === origin.protocol, "Detail redirects must stay on this storefront");
  return { status: response.status, html: await response.text(), finalPath: normalizePath(finalUrl.href) };
}

function mediaOf(scope, $) {
  return $(scope).find("img").first().attr("src")
    || $(scope).find("video").first().attr("src")
    || $(scope).find("video").first().attr("poster");
}

function expectedDirectoryProducts(audit) {
  const expected = new Map();
  for (const product of audit.products ?? []) {
    for (const placement of product.placements ?? []) {
      const path = text(placement?.placement);
      if (!path) continue;
      const products = expected.get(path) ?? new Set();
      products.add(product.productKey);
      expected.set(path, products);
    }
  }
  return expected;
}

const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
const audit = JSON.parse(fs.readFileSync(auditPath, "utf8"));
assert(Array.isArray(manifest.items) && manifest.items.length > 0, "Manifest has no items.");
assert(Array.isArray(audit.products) && audit.products.length > 0, "Audit has no products.");

const failures = [];
const directoryResults = [];
for (const [path, products] of [...expectedDirectoryProducts(audit)].sort(([left], [right]) => left.localeCompare(right))) {
  const expected = products.size;
  const { status, html } = await readPage(path);
  if (status !== 200) {
    failures.push(`${path}: expected 200, received ${status}`);
    continue;
  }
  const $ = cheerio.load(html);
  const section = $('section[class*="mediaSection"]').first();
  const cards = section.find("a.ti").map((index, element) => ({
    href: $(element).attr("href"),
    media: mediaOf(element, $)
  })).get();
  const hrefs = [...new Set(cards.map((card) => card.href).filter(Boolean))];
  const media = [...new Set(cards.map((card) => card.media).filter(Boolean))];
  const result = {
    path,
    expected,
    cards: cards.length,
    uniqueHrefs: hrefs.length,
    uniqueMedia: media.length
  };
  directoryResults.push(result);
  if (!section.length) failures.push(`${path}: media section is missing.`);
  if (cards.length !== expected) failures.push(`${path}: expected ${expected} cards, found ${cards.length}.`);
  if (hrefs.length !== cards.length) failures.push(`${path}: found ${cards.length - hrefs.length} duplicate detail links.`);
  if (media.length !== cards.length) failures.push(`${path}: found ${cards.length - media.length} duplicate media sources.`);
}

const detailResults = [];
for (const item of manifest.items) {
  const kind = text(item.expectedKind);
  assert(kind === "photo" || kind === "video", `Product ${item.productKey} has invalid kind.`);
  const root = kind === "photo" ? "/ai-image-generation/" : "/ai-video-generation/";
  const aliases = Array.isArray(item.publicSlugs)
    ? item.publicSlugs.filter((slug) => slug !== item.canonicalPublicSlug)
    : [];
  const slugs = [item.canonicalPublicSlug, ...(aliases.length ? [aliases[0]] : [])];
  for (const slug of slugs) {
    const pathname = root + slug;
    const { status, html, finalPath } = await readPage(pathname, true);
    if (status !== 200) {
      failures.push(`detail ${pathname}: expected 200, received ${status}`);
      continue;
    }
    const $ = cheerio.load(html);
    const allowed = new Set([item.canonicalPublicSlug, ...(item.publicSlugs ?? [])].map((value) => root + value));
    if (!allowed.has(finalPath)) failures.push(`detail ${pathname}: redirected outside its reviewed resource group (${finalPath}).`);
    const chips = $(".v-detail-categories a").map((index, element) => ({
      text: $(element).text().trim(),
      href: $(element).attr("href")
    })).get();
    const expectedPath = item.placement[0];
    const chipPaths = chips.map((chip) => normalizePath(chip.href));
    const ok = chips.length === 1 && chipPaths[0] === normalizePath(expectedPath);
    detailResults.push({
      path: pathname,
      canonical: slug === item.canonicalPublicSlug,
      chip: chips[0]?.text ?? null,
      href: chips[0]?.href ?? null,
      ok
    });
    if (!ok) failures.push(`detail ${pathname}: expected one chip to ${expectedPath}, found ${JSON.stringify(chips)}.`);
  }
}

const output = {
  ok: failures.length === 0,
  baseUrl,
  manifest: manifestPath,
  audit: auditPath,
  directories: directoryResults,
  details: verbose ? detailResults : {
    checked: detailResults.length,
    canonical: detailResults.filter((item) => item.canonical).length,
    aliases: detailResults.filter((item) => !item.canonical).length
  },
  failures
};
console.log(JSON.stringify(output, null, 2));
if (failures.length) process.exitCode = 1;
